// generation.go — the polynomials of S are generated by the constants
// and the variables. The generator at a monomial is the value of the
// monomial in the polynomials of S at the variables, the product of their
// powers. Two ring homomorphisms out of the polynomials of S that agree on
// the constants and the variables agree everywhere, the polynomials where
// they agree holding the constants and being closed under sums and under
// multiplication by the variables (polynomial_algebra's induction); and so
// a ring homomorphism ψ after an evaluation is an evaluation, at the
// values sent along ψ and along a coefficient map that agrees with ψ after
// the first. Over an integral domain the ideal one variable generates is
// prime: substituting zero for that variable keeps each polynomial in its
// class, so the ideal is the kernel of a ring map into a domain.

package polynomial_algebra_evaluation

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/integral_domain"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial_algebra"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/quotient_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_ideal"
	"github.com/euc-ai/xugo/library/proofs/nat_num/peano"
	"github.com/euc-ai/xugo/library/proofs/sets/finite_set"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/registry"
)

// MonomialAsProduct — the generator at a monomial m of S is the monomial
// evaluated in the polynomials of S at the variables, the product of the
// variables' powers. Raising the exponent of one variable x of S by one
// multiplies both sides by the variable x: the generator by the
// multiplication table of the generators
// (polynomial_algebra.PolynomialAlgebraGeneratorMul), the variable being
// the generator at the monomial of x, and the value by
// MonomialEvalShift, the variables of S being polynomials of S. At the
// monomial of the constants both sides are the one polynomial, the empty
// product. So the identity climbs, by induction on a finite set holding the
// variables of m, one variable at a time, and for each new variable by
// induction on its exponent.
var MonomialAsProduct = monomialAsProductThm{family.Add(registry.ProofEntry{
	Name: "MonomialAsProduct",
	Key:  "prop_a44240d36c6b8f4b",
	Reading: "The right side is the product, in the polynomials of S, of " +
		"polynomial_algebra_var(R, x) ^ m(x) over the variables x where m is nonzero. Of " +
		"m ∈ monomials(S) only the finite support is load-bearing, the ring operations " +
		"not reading S: the product is a fold over the variables of m, unspecified when " +
		"they are infinitely many. Over the zero ring both sides are the zero polynomial.",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). ∀S:set(D). ∀m:(D → num).",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"m ∈ monomials(S)",
		},
		Conclusion: "delta_at(m) = " +
			"monomial_eval(polynomial_algebra_ring(R, S), polynomial_algebra_var(R), m)",
		Abbrev: Abbrev{
			{Name: "asProduct", Text: "λn:(D → num). " +
				"    delta_at(n) = monomial_eval(polynomial_algebra_ring(R, S), polynomial_algebra_var(R), n)"},
			{Name: "asProductOver", Text: "λF:set(D). ∀n:(D → num). " +
				"    n ∈ monomials(S) ∧ (∀y:D. n(y) ≠ 0 ⇒ y ∈ F) ⇒ «asProduct»(n)"},
		},
	},
		func(a *Argument, R *Expr[RingOps[A]], S *Expr[Set[D]], m *Arrow[D, Nat], ring, monomial Fact) {
			polynomials := a.TermAs[RingOps[Fun[Fun[D, Nat], A]]]("polynomial_algebra_ring(R, S)")
			variables := a.TermAs[Fun[D, Fun[Fun[D, Nat], A]]]("polynomial_algebra_var(R)")
			values := a.Have(
				"every variable of S is a polynomial of S, a member of the carrier of the polynomials of S",
				"∀y:D. y ∈ S ⇒ polynomial_algebra_var(R, y) ∈ polynomial_algebra_ring(R, S).carrier",
				By(ring, polynomial_algebra.PolynomialAlgebraVarIn))
			raise := a.Have(
				"raising the exponent of a variable x of S by one "+
					"carries the identity from n to n + monomial_var(x)",
				Statement{
					Binders: "∀n:(D → num). ∀x:D.",
					Hypotheses: []string{
						"n ∈ monomials(S)",
						"x ∈ S",
						"«asProduct»(n)",
					},
					Conclusion: "«asProduct»(λy:D. n(y) + monomial_var(x, y))",
				},
				Derive(func(b *Argument) {
					n := b.FixAs[Fun[D, Nat]]("n")
					x := b.FixAs[D]("x")
					given := b.Conjuncts(
						b.Assume(),
						"n is a monomial of S",
						"x is a variable of S",
						"the generator at n is the monomial n evaluated at the variables")
					finite := b.Have(
						"n and the monomial of x, monomials of S, are finitely supported",
						"finite_support(0, n) ∧ finite_support(0, monomial_var(x))",
						BySets(
							given[0],
							given[1],
							polynomial_algebra.MonomialsDef,
							polynomial_algebra.MonomialVarIn.At(S, x)))
					swap := b.Have(
						"exponents add in either order",
						"(λy:D. monomial_var(x, y) + n(y)) = (λy:D. n(y) + monomial_var(x, y))",
						Funext(),
						ByArith())
					product := b.Have(
						"the variable x, the generator at the monomial of x, "+
							"times the generator at n is the generator at n raised at x",
						"polynomial_algebra_mul(R, polynomial_algebra_var(R, x), delta_at(n)) = "+
							"delta_at(λy:D. n(y) + monomial_var(x, y))",
						Simp(Fwd(polynomial_algebra.PolynomialAlgebraVarDef)),
						By(
							ring,
							swap,
							finite,
							polynomial_algebra.PolynomialAlgebraGeneratorMul.At(
								R, b.TermAs[Fun[D, Nat]]("monomial_var(x)"), n)))
					b.Show(
						"raising x multiplies the value by the variable x, and the value at n is the generator at n",
						By(
							given[0],
							given[1],
							given[2],
							product,
							values,
							ring,
							polynomial_algebra.PolynomialAlgebraCommRingOn.At(R, S),
							MonomialEvalShift.At(polynomials, S, variables, n, x)))
				}))
			constants := a.Have(
				"a monomial with no variable is the monomial of the "+
					"constants, where both sides are the one polynomial",
				"«asProductOver»(∅)",
				Derive(func(b *Argument) {
					b.FixAs[Fun[D, Nat]]("n")
					none := b.Assume()
					zero := b.Have(
						"n is zero at every variable",
						"n = (λx:D. 0)",
						Funext(),
						By(none, set_basic.NotInEmpty))
					empty := b.Have(
						"so n has no variable",
						"fun_support(0, n) = ∅",
						BySets(none))
					b.Show(
						"the empty product is the one polynomial, the generator at the monomial of the constants",
						Simp(Fwd(MonomialEvalDef)),
						empty.Rw(),
						Simp(Fwd(module.ModuleSumEmpty), Fwd(polynomial_algebra.PolynomialAlgebraOneDef)),
						zero.Rw(),
						Basic())
				}))
			insert := a.Have(
				"adding a variable x to s carries the identity from the monomials "+
					"of S with variables in s to those with variables in insert(x, s)",
				"∀x:D. ∀s:set(D). «asProductOver»(s) ⇒ «asProductOver»(insert(x, s))",
				Derive(func(b *Argument) {
					x := b.FixAs[D]("x")
					b.FixAs[Set[D]]("s")
					inS := b.Assume()
					byExponent := b.Have(
						"by induction on the exponent k of x, the identity holds at every "+
							"monomial n of S with its variables in insert(x, s) and exponent k at x",
						Statement{
							Binders: "∀k:num. ∀n:(D → num).",
							Hypotheses: []string{
								"n ∈ monomials(S)",
								"∀y:D. n(y) ≠ 0 ⇒ y ∈ insert(x, s)",
								"n(x) = k",
							},
							Conclusion: "«asProduct»(n)",
						},
						Derive(func(c *Argument) {
							c.Induct("k")
							c.Base(
								"at exponent zero the variables of n lie in s",
								func(d *Argument) {
									n := d.FixAs[Fun[D, Nat]]("n")
									given := d.Conjuncts(
										d.Assume(),
										"n is a monomial of S",
										"its variables lie in insert(x, s)",
										"its exponent at x is zero")
									inSet := d.Have(
										"x not being among them, the variables of n lie in s",
										"∀y:D. n(y) ≠ 0 ⇒ y ∈ s",
										By(given[1], given[2], set_basic.InInsert))
									d.Show(
										"where the identity holds",
										By(inS.At(n), given[0], inSet))
								})
							c.Step(
								"one more power of x: n is n₁ plus the monomial of x, and the identity at n₁ is raised at x",
								func(d *Argument, ih Fact) {
									d.FixAs[Fun[D, Nat]]("n")
									given := d.Conjuncts(
										d.Assume(),
										"n is a monomial of S",
										"its variables lie in insert(x, s)",
										"its exponent at x is suc(k)")
									xMonomial := d.Conjuncts(
										polynomial_algebra.MonomialVarValues.At(x),
										"the monomial of x is one at x",
										"and zero at every other variable")
									xIn := d.Have(
										"x, where n has a positive exponent, is a variable of S",
										"x ∈ S",
										BySets(
											given[0],
											given[2],
											polynomial_algebra.MonomialsDef,
											peano.SucNotZero.At(d.TermAs[Nat]("k"))))
									within := d.Have(
										"the monomial of x lies below n",
										"∀y:D. monomial_var(x, y) ≤ n(y)",
										Derive(func(e *Argument) {
											y := e.FixAs[D]("y")
											e.Cases(e.TermAs[Bool]("y = x"))
											e.When(
												"at x it is one, and n has suc(k) there",
												func(f *Argument, same Fact) {
													f.Show(
														"one is at most suc(k)",
														same.Rw(),
														ByArith(xMonomial[0], given[2]))
												})
											e.Otherwise(
												"elsewhere it is zero",
												func(f *Argument, off Fact) {
													f.Show(
														"and zero is at most every exponent",
														ByArith(off, xMonomial[1].At(y)))
												})
										}))
									n1, split := d.ObtainAs[Fun[D, Nat]](
										"so n is n₁ plus the monomial of x, for n₁ = n − monomial_var(x), below n with exponent k at x",
										"∃n₁:(D → num). n = (λy:D. n₁(y) + monomial_var(x, y)) ∧ n₁(x) = k ∧ (∀y:D. n₁(y) ≤ n(y))",
										Witness(d.TermAs[Fun[D, Nat]]("λy:D. n(y) - monomial_var(x, y)")),
										SplitConjAll(
											Case(
												"taking off the monomial of x and putting it back gives n",
												Funext(),
												ByArith(within)),
											Case(
												"the exponent at x drops from suc(k) to k",
												ByArith(given[2], xMonomial[0])),
											Case(
												"and no exponent grows",
												ByArith())))
									parts := d.Conjuncts(
										split,
										"n is n₁ plus the monomial of x",
										"n₁ has exponent k at x",
										"n₁ lies below n")
									inN := d.Have(
										"a variable of n₁ is a variable of n",
										"∀y:D. n₁(y) ≠ 0 ⇒ n(y) ≠ 0",
										ByArith(parts[2]))
									monomial1 := d.Have(
										"so n₁ is a monomial of S",
										"n₁ ∈ monomials(S)",
										BySets(
											inN,
											given[0],
											polynomial_algebra.MonomialsMember,
											finite_set.FiniteSubset.At(
												d.TermAs[Set[D]]("fun_support(0, n₁)"), d.TermAs[Set[D]]("fun_support(0, n)"))))
									inInsert := d.Have(
										"with its variables in insert(x, s)",
										"∀y:D. n₁(y) ≠ 0 ⇒ y ∈ insert(x, s)",
										By(inN, given[1]))
									d.Show(
										"the identity at n₁, from exponent k, raised at x",
										By(parts[0], parts[1], monomial1, inInsert, xIn, ih.At(n1), raise.At(n1, x)))
								})
						}))
					b.Show(
						"so it holds at every monomial n of S with its variables in insert(x, s), at its own exponent of x",
						Derive(func(c *Argument) {
							n := c.FixAs[Fun[D, Nat]]("n")
							c.Show(
								"at k = n(x)",
								By(c.Assume(), byExponent.At(c.TermAs[Nat]("n(x)"), n)))
						}))
				}))
			predicate := a.TermAs[Set[Set[D]]]("«asProductOver»")
			overFinite := a.Have(
				"so the identity holds at every monomial of S whose variables lie in a finite set F",
				"∀F:set(D). finite(F) ⇒ «asProductOver»(F)",
				Derive(func(b *Argument) {
					F := b.FixAs[Set[D]]("F")
					b.Show(
						"by induction on the finite set F, from no variable, one variable at a time",
						By(finite_set.FiniteInduct.At(predicate, F), constants, insert, b.Assume()))
				}))
			support := a.TermAs[Set[D]]("fun_support(0, m)")
			finite := a.Have(
				"m, a monomial of S, has finitely many variables",
				"finite(fun_support(0, m))",
				By(monomial, polynomial_algebra.MonomialSupport.At(S, m)))
			a.Show(
				"and they lie in its own finite support",
				By(monomial, finite, overFinite.At(support, m)))
		}),
})}

// PolynomialAlgebraEvalUnique — two ring homomorphisms out of the
// polynomials of S that agree on the constants and on the variables of S
// agree on every polynomial of S. The polynomials of S on which they agree
// hold the constants, themselves polynomials of S, and are closed under
// sums and under multiplication by a variable of S, which both maps keep;
// so by polynomial_algebra.PolynomialInduction they hold every polynomial of S.
var PolynomialAlgebraEvalUnique = polynomialAlgebraEvalUniqueThm{family.Add(registry.ProofEntry{
	Name: "PolynomialAlgebraEvalUnique",
	Key:  "prop_81f8ddba5daa6b0f",
	Reading: "The two maps are compared on the constants of R's carrier only and " +
		"on the variables of S only: these generate the polynomials of S as a ring.",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). " +
			"∀R':ring_ops(B). " +
			"∀S:set(D). " +
			"∀F G:(((D → num) → A) → B). " +
			"∀f:((D → num) → A).",
		Hypotheses: []string{
			"comm_ring_on(R)",
			"ring_homomorphism(polynomial_algebra_ring(R, S), R', F)",
			"ring_homomorphism(polynomial_algebra_ring(R, S), R', G)",
			"∀a:A. a ∈ R.carrier ⇒ F(polynomial_algebra_const(R, a)) = G(polynomial_algebra_const(R, a))",
			"∀x:D. x ∈ S ⇒ F(polynomial_algebra_var(R, x)) = G(polynomial_algebra_var(R, x))",
			"f ∈ polynomial_algebra(R, S)",
		},
		Conclusion: "F(f) = G(f)",
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			RPrime *Expr[RingOps[B]],
			S *Expr[Set[D]],
			F, G *Arrow[Fun[Fun[D, Nat], A], B],
			f *Arrow[Fun[D, Nat], A],
			ring, homF, homG, constants, variables, fIn Fact,
		) {
			type poly = Fun[Fun[D, Nat], A]
			agree, agreeDef := a.LetAs[Set[poly]](
				"C",
				"{g:((D → num) → A) | g ∈ polynomial_algebra(R, S) ∧ F(g) = G(g)}")
			constantsIn := a.Have(
				"the constants are polynomials of S on which F and G agree",
				"∀c:A. c ∈ R.carrier ⇒ polynomial_algebra_const(R, c) ∈ C",
				BySets(
					agreeDef,
					ring,
					constants,
					polynomial_algebra.PolynomialAlgebraConstHom.At(R, S),
					ring_homomorphism.MapIn))
			sumsIn := a.Have(
				"they are closed under sums, which F and G keep",
				"∀g h:((D → num) → A). g ∈ C ∧ h ∈ C ⇒ fun_add(g, h) ∈ C",
				Derive(func(b *Argument) {
					g, h := b.FixAs[poly]("g"), b.FixAs[poly]("h")
					parts := b.Conjuncts(
						b.Have(
							"g and h are polynomials of S on which F and G agree",
							"g ∈ polynomial_algebra(R, S) ∧ F(g) = G(g) ∧ h ∈ polynomial_algebra(R, S) ∧ F(h) = G(h)",
							BySets(b.Assume(), agreeDef)),
						"g is a polynomial of S",
						"F and G agree at g",
						"h is a polynomial of S",
						"F and G agree at h")
					b.Show(
						"g + h is a polynomial of S, and F and G take it to the sum of their values",
						BySets(
							agreeDef,
							parts[0],
							parts[1],
							parts[2],
							parts[3],
							comm_ring.AddIn.Read(ring_homomorphism.Source.Read(homF)),
							At(ring_homomorphism.MapAdd.Read(homF), g, h),
							At(ring_homomorphism.MapAdd.Read(homG), g, h)))
				}))
			variablesIn := a.Have(
				"and under multiplication by a variable of S, F and "+
					"G keeping products and agreeing on the variables",
				Statement{
					Binders:    "∀x:D. ∀g:((D → num) → A).",
					Hypotheses: []string{"x ∈ S", "g ∈ C"},
					Conclusion: "polynomial_algebra_mul(R, polynomial_algebra_var(R, x), g) ∈ C",
				},
				Derive(func(b *Argument) {
					x := b.FixAs[D]("x")
					g := b.FixAs[poly]("g")
					given := b.Conjuncts(
						b.Assume(),
						"x is a variable of S",
						"g lies in C")
					parts := b.Conjuncts(
						b.Have(
							"g is a polynomial of S on which F and G agree",
							"g ∈ polynomial_algebra(R, S) ∧ F(g) = G(g)",
							BySets(given[1], agreeDef)),
						"g is a polynomial of S",
						"F and G agree at g")
					variable := b.TermAs[poly]("polynomial_algebra_var(R, x)")
					variableIn := b.Have(
						"the variable x is a polynomial of S",
						"polynomial_algebra_var(R, x) ∈ polynomial_algebra(R, S)",
						By(ring, given[0], polynomial_algebra.PolynomialAlgebraVarIn.At(R, S, x)))
					b.Show(
						"the variable x times g is a polynomial of S, and F and G take it to the product of their values",
						BySets(
							agreeDef,
							ring,
							given[0],
							variableIn,
							parts[0],
							parts[1],
							variables.At(x),
							polynomial_algebra.PolynomialAlgebraMulIn.At(R, S, variable, g),
							At(ring_homomorphism.MapMul.Read(homF), variable, g),
							At(ring_homomorphism.MapMul.Read(homG), variable, g)))
				}))
			covered := a.Have(
				"so every polynomial of S lies in C, by induction on the polynomials",
				"polynomial_algebra(R, S) ⊆ C",
				By(ring, constantsIn, sumsIn, variablesIn, polynomial_algebra.PolynomialInduction.At(R, S, agree)))
			a.Show(
				"and f is one of them",
				BySets(fIn, covered, agreeDef))
		}),
})}

// PolynomialAlgebraEvalNatural — evaluation is natural in its target: a
// ring map ψ out of T carries the value in T of a polynomial at θ, its
// coefficients sent along φ, to its value in U at ψ∘θ, its coefficients
// sent along a ring map χ that agrees with ψ∘φ on R. Both sides are ring
// homomorphisms out of the polynomials of S, the one ψ after evaluation
// into T, and they agree on the constants and on the variables.
var PolynomialAlgebraEvalNatural = polynomialAlgebraEvalNaturalThm{family.Add(registry.ProofEntry{
	Name: "PolynomialAlgebraEvalNatural",
	Key:  "prop_eea19f1559f1b146",
	Build: family.Theorem(Statement{
		Binders: "∀R:ring_ops(A). " +
			"∀T:ring_ops(B). " +
			"∀U:ring_ops(C). " +
			"∀φ:(A → B). " +
			"∀ψ:(B → C). " +
			"∀χ:(A → C). " +
			"∀S:set(D). " +
			"∀θ:(D → B). " +
			"∀f:((D → num) → A).",
		Hypotheses: []string{
			"ring_homomorphism(R, T, φ)",
			"ring_homomorphism(T, U, ψ)",
			"ring_homomorphism(R, U, χ)",
			"∀a:A. a ∈ R.carrier ⇒ ψ(φ(a)) = χ(a)",
			"∀x:D. x ∈ S ⇒ θ(x) ∈ T.carrier",
			"f ∈ polynomial_algebra(R, S)",
		},
		Conclusion: "ψ(polynomial_algebra_eval(R, T, φ, θ, f)) = " +
			"polynomial_algebra_eval(R, U, χ, λx:D. ψ(θ(x)), f)",
	},
		func(
			a *Argument,
			R *Expr[RingOps[A]],
			T *Expr[RingOps[B]],
			U *Expr[RingOps[C]],
			φ *Arrow[A, B],
			ψ *Arrow[B, C],
			χ *Arrow[A, C],
			S *Expr[Set[D]],
			θ *Arrow[D, B],
			f *Arrow[Fun[D, Nat], A],
			given Fact,
		) {
			parts := a.Conjuncts(
				given,
				"φ is a ring map from R to T",
				"ψ is a ring map from T to U",
				"χ is a ring map from R to U",
				"ψ after φ is χ on R",
				"θ lands in T on S",
				"f is a polynomial of S")
			intoT, alongψ, intoU, agree, θInT, fIn := parts[0], parts[1], parts[2], parts[3], parts[4], parts[5]
			pushed := a.TermAs[Fun[D, C]]("λx:D. ψ(θ(x))")
			evaluationT := a.Have(
				"evaluation into T is a ring homomorphism out of the polynomials of S",
				"ring_homomorphism(polynomial_algebra_ring(R, S), T, polynomial_algebra_eval(R, T, φ, θ))",
				By(θInT, intoT, PolynomialAlgebraEvalHom.At(R, T, φ, θ, S)))
			composite := a.Have(
				"and so is ψ after it",
				"ring_homomorphism(polynomial_algebra_ring(R, S), "+
					"    U, "+
					"    λg:((D → num) → A). ψ(polynomial_algebra_eval(R, T, φ, θ, g)))",
				By(evaluationT, alongψ, ring_homomorphism.RingHomCompose))
			evaluationU := a.Have(
				"evaluation into U at ψ∘θ is one too",
				"ring_homomorphism(polynomial_algebra_ring(R, S), "+
					"    U, "+
					"    polynomial_algebra_eval(R, U, χ, λx:D. ψ(θ(x))))",
				By(
					intoU,
					θInT,
					PolynomialAlgebraEvalHom.At(R, U, χ, pushed, S),
					ring_homomorphism.MapIn.Read(alongψ)))
			constants := a.Have(
				"the two agree on the constants, both ψ(φ(c)) = χ(c)",
				Statement{
					Binders:    "∀c:A.",
					Hypotheses: []string{"c ∈ R.carrier"},
					Conclusion: "ψ(polynomial_algebra_eval(R, T, φ, θ, polynomial_algebra_const(R, c))) = " +
						"polynomial_algebra_eval(R, U, χ, λx:D. ψ(θ(x)), polynomial_algebra_const(R, c))",
				},
				Derive(func(b *Argument) {
					c := b.FixAs[A]("c")
					cIn := b.Assume()
					b.Show(
						"a constant evaluates to its coefficient sent along the map",
						By(
							intoT,
							intoU,
							agree.At(c),
							cIn,
							PolynomialAlgebraEvalConst.At(R, T, φ, θ, c),
							PolynomialAlgebraEvalConst.At(R, U, χ, pushed, c)))
				}))
			variables := a.Have(
				"and on the variables of S, both ψ(θ(y))",
				Statement{
					Binders:    "∀y:D.",
					Hypotheses: []string{"y ∈ S"},
					Conclusion: "ψ(polynomial_algebra_eval(R, T, φ, θ, polynomial_algebra_var(R, y))) = " +
						"polynomial_algebra_eval(R, U, χ, λx:D. ψ(θ(x)), polynomial_algebra_var(R, y))",
				},
				Derive(func(b *Argument) {
					y := b.FixAs[D]("y")
					yIn := b.Assume()
					b.Show(
						"a variable evaluates to its value",
						By(
							intoT,
							intoU,
							θInT.At(y),
							yIn,
							alongψ,
							PolynomialAlgebraEvalVar.At(R, T, φ, θ, y),
							PolynomialAlgebraEvalVar.At(R, U, χ, pushed, y),
							ring_homomorphism.MapIn.Read(alongψ).AsFact().At(θ.Apply(y))))
				}))
			a.Show(
				"so the two homomorphisms agree on every polynomial of S",
				By(
					intoT,
					composite,
					evaluationU,
					constants,
					variables,
					fIn,
					PolynomialAlgebraEvalUnique.At(
						R,
						U,
						S,
						a.TermAs[Fun[Fun[Fun[D, Nat], A], C]](
							"λg:((D → num) → A). ψ(polynomial_algebra_eval(R, T, φ, θ, g))"),
						a.TermAs[Fun[Fun[Fun[D, Nat], A], C]]("polynomial_algebra_eval(R, U, χ, λx:D. ψ(θ(x)))"),
						f),
					ring_homomorphism.Source.Read(intoT)))
		}),
})}

// VariableIdealPrime — over an integral domain R, the ideal a variable x
// generates among the polynomials in the variables S is prime. Substituting
// zero for x and keeping every other variable is a ring map ρ of the
// polynomials into themselves. Modulo the ideal ρ moves nothing: the
// projection onto the quotient and the projection after ρ are ring maps out
// of the polynomials that agree on the constants, which ρ fixes, and on the
// variables, ρ fixing every variable but x and sending x to zero, x and zero
// both lying in the ideal (PolynomialAlgebraEvalUnique). So a polynomial ρ
// kills lies in the ideal, and ρ kills the ideal, which x generates: the ideal
// is the kernel of ρ, a ring map into a domain
// (polynomial_algebra.PolynomialAlgebraDomain), so it misses one and holds a
// factor of each product it holds.
var VariableIdealPrime = variableIdealPrimeThm{family.Add(registry.ProofEntry{
	Name: "VariableIdealPrime",
	Key:  "prop_18beb27b417144bc",
	Reading: "That R is a domain is load-bearing: modulo x the polynomials are those over " +
		"R in the other variables, a domain exactly when R is one. S is any set of variables, " +
		"of any type and any size, x one of them; at S = {x} the quotient is R itself.",
	Build: family.Theorem(Statement{
		Binders: "∀R:integral_domain_on(A). ∀S:set(D). ∀x:D.",
		Hypotheses: []string{
			"x ∈ S",
		},
		Conclusion: "prime_ideal(polynomial_algebra_ring(R, S), «ideal»)",
		Abbrev: Abbrev{
			{Name: "ideal", Text: "ideal_span(polynomial_algebra_ring(R, S), {polynomial_algebra_var(R, x)})"},
			// ρ: zero for x, every other variable kept, the constants fixed.
			{Name: "substitution", Text: "polynomial_algebra_eval(R, " +
				"    polynomial_algebra_ring(R, S), " +
				"    polynomial_algebra_const(R), " +
				"    λy:D. COND(y = x, fun_zero, polynomial_algebra_var(R, y)))"},
			{Name: "projection", Text: "ideal_quotient_projection(polynomial_algebra_ring(R, S), «ideal»)"},
		},
	}, func(
		a *Argument,
		R integral_domain.IntegralDomainFact[on.R],
		S *Expr[Set[D]],
		x *Expr[D],
		xIn Fact,
	) {
		type polynomial = Fun[Fun[D, Nat], A]
		ringR := a.TermAs[RingOps[A]]("R")
		polynomialRing := a.TermAs[RingOps[polynomial]]("polynomial_algebra_ring(R, S)")
		ideal := a.TermAs[Set[polynomial]]("«ideal»")
		generator := a.TermAs[polynomial]("polynomial_algebra_var(R, x)")
		zero := a.TermAs[polynomial]("fun_zero")
		ring := integral_domain.Ring.Read(R)
		domain := a.Have(
			"the polynomials over the domain R are a domain",
			"integral_domain_on(polynomial_algebra_ring(R, S))",
			By(polynomial_algebra.PolynomialAlgebraDomain.Read(R).At(S)))
		polynomials := integral_domain.Ring.Read(domain)
		constants := a.Have(
			"the constants are a ring map of R into the polynomials",
			"ring_homomorphism(R, polynomial_algebra_ring(R, S), polynomial_algebra_const(R))",
			By(ring, polynomial_algebra.PolynomialAlgebraConstHom))
		values := a.Have(
			"zero and the variables are polynomials",
			"∀y:D. y ∈ S ⇒ COND(y = x, fun_zero, polynomial_algebra_var(R, y)) ∈ polynomial_algebra(R, S)",
			By(ring, comm_ring.ZeroIn.Read(polynomials), polynomial_algebra.PolynomialAlgebraVarIn))
		substitution := a.Have(
			"so substituting zero for x, every other variable kept, "+
				"is a ring map ρ of the polynomials into themselves",
			"ring_homomorphism(polynomial_algebra_ring(R, S), polynomial_algebra_ring(R, S), «substitution»)",
			By(values, constants, PolynomialAlgebraEvalHom))
		onVariables := a.Have(
			"ρ sends x to zero and every other variable to itself",
			Statement{
				Binders:    "∀y:D.",
				Hypotheses: []string{"y ∈ S"},
				Conclusion: "«substitution»(polynomial_algebra_var(R, y)) = " +
					"COND(y = x, fun_zero, polynomial_algebra_var(R, y))",
			},
			By(values, constants, PolynomialAlgebraEvalVar))
		isIdeal := a.Have(
			"x generates an ideal of the polynomials",
			"ring_ideal(polynomial_algebra_ring(R, S), «ideal»)",
			By(
				ring,
				xIn,
				ring_ideal.SpanIdeal.Read(polynomials).At(
					a.TermAs[Set[polynomial]]("{polynomial_algebra_var(R, x)}")),
				polynomial_algebra.PolynomialAlgebraVarIn.At(ringR, S, x),
				set_order.SingSubset))
		quotient := a.Have(
			"the projection onto the quotient by the ideal, after ρ, is a ring map",
			"ring_homomorphism(polynomial_algebra_ring(R, S), "+
				"    ideal_quotient_ring(polynomial_algebra_ring(R, S), «ideal»), "+
				"    λf:((D → num) → A). «projection»(«substitution»(f)))",
			By(
				isIdeal,
				substitution,
				quotient_ring.ProjectionHomomorphism.Read(polynomials),
				ring_homomorphism.RingHomCompose))
		zeroClass := a.Have(
			"zero lies in the ideal, so its class is the ideal",
			"«projection»(fun_zero) = «ideal»",
			By(
				isIdeal,
				comm_ring.ZeroIn.Read(polynomials),
				quotient_ring.IdealQuotientProjectionDef.At(polynomialRing, ideal, zero),
				quotient_ring.CosetEqIdealIff.Read(polynomials).AsFact().At(ideal, zero),
				ring_ideal.IdealZero.At(polynomialRing, ideal)))
		generatorClass := a.Have(
			"so does x, which generates it",
			"«projection»(polynomial_algebra_var(R, x)) = «ideal»",
			By(
				ring,
				isIdeal,
				xIn,
				polynomial_algebra.PolynomialAlgebraVarIn.At(ringR, S, x),
				ring_ideal.SpanContains.At(
					polynomialRing, a.TermAs[Set[polynomial]]("{polynomial_algebra_var(R, x)}")),
				set_order.SingSubset.At(ideal, generator),
				quotient_ring.IdealQuotientProjectionDef.At(polynomialRing, ideal, generator),
				quotient_ring.CosetEqIdealIff.Read(polynomials).AsFact().At(ideal, generator)))
		killsGenerator := a.Have(
			"ρ kills x",
			"«substitution»(polynomial_algebra_var(R, x)) = fun_zero",
			By(onVariables.At(x), xIn))
		agreeOnConstants := a.Have(
			"the projection and the projection after ρ agree on the constants, which ρ fixes",
			Statement{
				Binders:    "∀c:A.",
				Hypotheses: []string{"c ∈ R.carrier"},
				Conclusion: "«projection»(polynomial_algebra_const(R, c)) = " +
					"«projection»(«substitution»(polynomial_algebra_const(R, c)))",
			},
			By(constants, PolynomialAlgebraEvalConst))
		agreeOnVariables := a.Have(
			"and on the variables: ρ fixes every one but x, and x and zero have one class",
			Statement{
				Binders:    "∀y:D.",
				Hypotheses: []string{"y ∈ S"},
				Conclusion: "«projection»(polynomial_algebra_var(R, y)) = " +
					"«projection»(«substitution»(polynomial_algebra_var(R, y)))",
			},
			Derive(func(b *Argument) {
				y := b.FixAs[D]("y")
				yIn := b.Assume()
				b.Cases(b.Term("y = x"))
				b.When(
					"at x, ρ gives zero, whose class is that of x",
					func(c *Argument, atX Fact) {
						c.Show(
							"both sides are the ideal",
							atX.Rw(),
							By(killsGenerator, zeroClass, generatorClass))
					})
				b.Otherwise(
					"at another variable, ρ keeps it",
					func(c *Argument, other Fact) {
						c.Show(
							"both sides are its class",
							By(other, yIn, onVariables.At(y)))
					})
			}))
		agree := a.Have(
			"so the two ring maps agree on every polynomial: ρ keeps each polynomial in its class",
			Statement{
				Binders:    "∀f:((D → num) → A).",
				Hypotheses: []string{"f ∈ polynomial_algebra(R, S)"},
				Conclusion: "«projection»(f) = «projection»(«substitution»(f))",
			},
			By(
				ring,
				agreeOnConstants,
				agreeOnVariables,
				isIdeal,
				quotient,
				quotient_ring.ProjectionHomomorphism.Read(polynomials),
				Where(PolynomialAlgebraEvalUnique, "F", a.TermAs[Fun[polynomial, Set[polynomial]]]("«projection»")).
					Where(
						"G",
						a.TermAs[Fun[polynomial, Set[polynomial]]]("λf:((D → num) → A). «projection»(«substitution»(f))"))))
		killedIn := a.Have(
			"a polynomial ρ kills has the class of zero, so it lies in the ideal",
			"∀f:((D → num) → A). f ∈ polynomial_algebra(R, S) ∧ «substitution»(f) = fun_zero ⇒ f ∈ «ideal»",
			a.ForEach(func(f *Expr[polynomial]) Action {
				return By(
					agree.At(f),
					zeroClass,
					isIdeal,
					quotient_ring.IdealQuotientProjectionDef.At(polynomialRing, ideal, f),
					quotient_ring.CosetEqIdealIff.Read(polynomials).AsFact().At(ideal, f))
			}))
		kernel := a.Have(
			"so ρ kills the ideal x generates",
			"«ideal» ⊆ ring_kernel(fun_zero, polynomial_algebra(R, S), «substitution»)",
			By(
				ring,
				killsGenerator,
				xIn,
				ring_homomorphism.IdealSpanInKernel.Read(substitution).AsFact().At(
					a.TermAs[Set[polynomial]]("{polynomial_algebra_var(R, x)}")),
				polynomial_algebra.PolynomialAlgebraVarIn.At(ringR, S, x),
				set_order.SingSubset.At(a.TermAs[Set[polynomial]]("polynomial_algebra(R, S)"), generator),
				set_basic.InSing.Inst[polynomial]()))
		killed := a.Have(
			"each member of the ideal is killed by ρ",
			"∀f:((D → num) → A). f ∈ «ideal» ⇒ «substitution»(f) = fun_zero",
			BySets(kernel, ring_homomorphism.RingKernelDef))
		a.Show(
			"so the ideal, the kernel of a ring map into a domain, is prime",
			Simp(Fwd(ring_ideal.PrimeIdealDef)),
			SplitConjAll(
				Case(
					"it is an ideal",
					By(isIdeal)),
				Case(
					"it misses one, which ρ sends to one and not to zero",
					By(killed, ring_homomorphism.MapOne.Read(substitution), integral_domain.OneNotZero.Read(domain))),
				Case(
					"a product in it has a factor in it: ρ sends the product to "+
						"zero, so one factor to zero, the polynomials being a domain",
					Derive(func(b *Argument) {
						f := b.FixAs[polynomial]("f")
						g := b.FixAs[polynomial]("g")
						product := b.Assume()
						b.Show(
							"the factor ρ kills lies in the ideal",
							By(
								product,
								killed.At(b.TermAs[polynomial]("polynomial_algebra_mul(R, f, g)")),
								killedIn.At(f),
								killedIn.At(g),
								ring_homomorphism.MapMul.Read(substitution).AsFact().At(f, g),
								ring_homomorphism.MapIn.Read(substitution).AsFact().At(f),
								ring_homomorphism.MapIn.Read(substitution).AsFact().At(g),
								integral_domain.NoZeroDivisors.Read(domain)))
					}))))
	}),
})}
